import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  Easing,
} from '../remotionShim';
// ------------------------------------------------------------------
// FONT LOADER
// ------------------------------------------------------------------
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;700;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// ------------------------------------------------------------------
// SCHEMA
// ------------------------------------------------------------------


export type RollingTextProps = Record<string, any>;

// ------------------------------------------------------------------
// SUB-COMPONENT: Single Character Column
// ------------------------------------------------------------------
const CharacterColumn: React.FC<{
  char: string;
  index: number;
  config: RollingTextProps;
  fps: number;
  frame: number;
}> = ({ char, index, config, fps, frame }) => {
  const {
    duplicateCount,
    rollDuration,
    staggerDelay,
    blurIntensity,
    textColor,
    fontSize,
    animationPattern,
  } = config;

  const lineHeight = fontSize; // using 1em effectively
  const totalHeight = lineHeight * duplicateCount;
  
  // Logic from Framer:
  // We want to scroll so that we see the character clearly at the end.
  // The column contains `duplicateCount` copies of the character.
  // We are viewing a window of height `fontSize`.
  // Movement is `(duplicateCount - 1) * fontSize`.
  const travelDistance = lineHeight * (duplicateCount - 1);

  // Timing
  const startFrame = index * staggerDelay * fps;
  const durationFrames = rollDuration * fps;
  
  // Progress 0 -> 1
  const progress = interpolate(
    frame,
    [startFrame, startFrame + durationFrames],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.bezier(0.25, 0.46, 0.45, 0.94),
    }
  );

  // Blur Logic: 0 -> blur -> blur -> 0
  const currentBlur = interpolate(
    progress,
    [0, 0.2, 0.8, 1],
    [0, blurIntensity, blurIntensity, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Direction Logic
  // Framer: isOddPosition (index % 2 === 0) -> Normal
  // If alternating and !isOddPosition -> Reverse
  const isEvenIndex = index % 2 === 0; // 0, 2, 4...
  const reverse = animationPattern === "alternating" && !isEvenIndex;

  // Calculate Y Position
  // Normal: Start at 0, move to -travelDistance (UP)
  // Reverse: Start at -travelDistance, move to 0 (DOWN)
  
  let translateY = 0;
  if (reverse) {
    translateY = interpolate(progress, [0, 1], [-travelDistance, 0]);
  } else {
    translateY = interpolate(progress, [0, 1], [0, -travelDistance]);
  }

  // Create array of chars
  const chars = useMemo(
    () => Array(duplicateCount).fill(char),
    [duplicateCount, char]
  );

  return (
    <div
      style={{
        position: "relative",
        height: fontSize,
        width: "auto", // width fits character
        overflow: "hidden",
        display: "flex",
        flexDirection: "column",
        justifyContent: "flex-start",
        alignItems: "center",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          transform: `translateY(${translateY}px)`,
          willChange: "transform",
        }}
      >
        {chars.map((c, i) => (
          <div
            key={i}
            style={{
              height: fontSize,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              color: textColor,
              fontSize: fontSize,
              lineHeight: "1em",
              filter: `blur(${currentBlur}px)`,
              // Prevent layout shift during blur
              transform: "translateZ(0)",
            }}
          >
            {c === " " ? "\u00A0" : c}
          </div>
        ))}
      </div>
    </div>
  );
};

// ------------------------------------------------------------------
// MAIN COMPONENT
// ------------------------------------------------------------------
const RollingText: React.FC<RollingTextProps> = ({
  text = "ROLLING",
  fontSize = 120,
  textColor = "#ffffff",
  duplicateCount = 8,
  rollDuration = 2,
  staggerDelay = 0.1,
  blurIntensity = 8,
  animationPattern = "sequential",
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 5,
}) => {
  // Load Fonts
  useFontLoader(["Inter"]);

  const { fps, width, height } = useVideoConfig();
  const frame = useCurrentFrame();

  const charArray = useMemo(() => text.split(""), [text]);

  const bgColor = transparentBackground
    ? "transparent"
    : backgroundColor;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter, sans-serif",
        fontWeight: 900,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "row",
          gap: fontSize * 0.05, // small gap between letters
        }}
      >
        {charArray.map((char, i) => (
          <CharacterColumn
            key={`${char}-${i}`}
            char={char}
            index={i}
            config={{
              text,
              fontSize,
              textColor,
              duplicateCount,
              rollDuration,
              staggerDelay,
              blurIntensity,
              animationPattern,
              backgroundColor,
              transparentBackground,
              durationInSeconds,
            }}
            fps={fps}
            frame={frame}
          />
        ))}
      </div>
    </AbsoluteFill>
  );
};

export default RollingText;